head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > P > tooltipShowAlways]<br/>컴포넌트의 아이템에 마우스를 올렸을때 라벨값을 툴팁으로 표시할지 여부를 설정합니다.",
    "validation" : [        
        "tooltipDisplay 속성에 의해 툴팁이 표시되는 경우만 동작하여야 합니다.",
        "툴팁이 표시될 때까지 기다릴 시간을 초 단위 숫자로 설정할 수 있어야 합니다.",
        "값을 설정하지 않으면 1 로 적용됩니다.",
        "tooltip 속성에 의해 표시되는 툴팁에는 적용되지 않아야 합니다.",
    ]
} 



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        tooltip: "tooltip",
        tooltipDisplay: true,
        tooltipTime: con_tooltipTime.getValue(),
        tooltipShowAlways: true,
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);     

    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" dataType="listed" tooltipGroupClass="false" style="width:200px;">';
    strTarget += '<w2:itemset nodeset="data:dlt_Item">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref=""></w2:folder>';
    strTarget += '<w2:checkbox ref=""></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref=""></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    ); 
}



scwin.target1_onclick = function (e) { 
    $c.gcm.getTooltipInfo(wf_body_bottom);
}
